SCRIPT = r"""
(() => {
  'use strict';
  const list = document.getElementById('alert-list');
  if (list) {
    const rows = Array.from(list.querySelectorAll('[data-alert]'));
    const search = document.getElementById('filter');
    const technique = document.getElementById('technique');
    const sort = document.getElementById('sort');
    const previous = document.getElementById('previous');
    const next = document.getElementById('next');
    let page = 0;
    const size = 8;
    const query = new URLSearchParams(location.search).get('technique');
    if (Array.from(technique.options).some(option => option.value === query)) technique.value = query;
    const update = () => {
      const q = search.value.trim().toLowerCase();
      const selected = rows.filter(row => {
        const techniques = row.dataset.techniques.split(' ').filter(Boolean);
        return (row.dataset.user.toLowerCase().includes(q) || row.dataset.alertId.toLowerCase().includes(q))
          && (!technique.value || (technique.value === 'unmapped' ? !techniques.length : techniques.includes(technique.value)));
      }).sort((a,b) => sort.value === 'time'
        ? b.dataset.time.localeCompare(a.dataset.time) || Number(b.dataset.score)-Number(a.dataset.score)
        : Number(b.dataset.score)-Number(a.dataset.score) || b.dataset.time.localeCompare(a.dataset.time));
      page = Math.min(page, Math.max(0, Math.ceil(selected.length/size)-1));
      const shown = new Set(selected.slice(page*size,(page+1)*size));
      rows.forEach(row => { row.hidden = !shown.has(row); });
      selected.forEach(row => list.appendChild(row));
      document.getElementById('empty').hidden = selected.length !== 0;
      document.getElementById('queue-status').textContent = selected.length
        ? String(page*size+1) + '–' + String(Math.min((page+1)*size,selected.length)) + ' of ' + selected.length + ' matching alert windows'
        : '0 matching alert windows';
      previous.disabled = page === 0;
      next.disabled = (page+1)*size >= selected.length;
    };
    [search,technique,sort].forEach(input => input.addEventListener(input === search ? 'input' : 'change', () => {page=0;update();}));
    document.getElementById('reset').addEventListener('click', () => {search.value='';technique.value='';sort.value='score';page=0;update();});
    previous.addEventListener('click', () => {page--;update();});
    next.addEventListener('click', () => {page++;update();});
    update();
  }
  const cells = Array.from(document.querySelectorAll('[data-technique]'));
  const panels = Array.from(document.querySelectorAll('[data-detail]'));
  if (cells.length) {
    const select = id => {
      if (!panels.some(panel => panel.dataset.detail === id)) id = panels[0].dataset.detail;
      panels.forEach(panel => {panel.hidden = panel.dataset.detail !== id;});
      cells.forEach(cell => cell.setAttribute('aria-pressed', String(cell.dataset.technique === id)));
    };
    cells.forEach(cell => cell.addEventListener('click', () => {
      select(cell.dataset.technique);
      history.replaceState(null, '', '#' + encodeURIComponent(cell.dataset.technique));
    }));
    window.addEventListener('hashchange', () => select(location.hash.slice(1)));
    select(location.hash.slice(1));
  }
})();
"""

